return [
  {
    json: {
      source: 'health',
      statusCode: 200,
      body: { status: 'ok', version: 'v1', time: '2026-01-15T10:00:00.000Z' },
    },
  },
  {
    json: {
      source: 'usage',
      statusCode: 200,
      body: {
        tier: 'synthetic-demo',
        status: 'active',
        periodEnd: '2026-01-31T23:59:59.000Z',
        limits: [
          { key: 'signals_monthly', max: 1000, used: 825, period: 'monthly' },
          { key: 'api_requests_daily', max: 5000, used: 1400, period: 'daily' },
        ],
      },
    },
  },
  {
    json: {
      source: 'reports',
      statusCode: 200,
      body: {
        format: 'pipsync.reports.catalog.v1',
        generatedAt: '2026-01-15T10:00:00.000Z',
        data: [
          { id: 'trades', title: 'Trade report', description: 'Synthetic', status: 'available', permission: 'read:trades', href: '/api/v1/reports/trades', formats: ['json', 'csv', 'pdf'], filters: [] },
          { id: 'demo-planned', title: 'Planned report', description: 'Synthetic', status: 'planned', permission: 'read:reports', href: null, formats: ['json'], filters: [] },
        ],
        meta: { count: 2, available: 1, planned: 1 },
      },
    },
  },
];

const rows = $input.all().map((item) => item.json).filter((item) => item && typeof item === 'object');
const bySource = Object.fromEntries(rows.map((item) => [item.source, item]));
const thresholdCandidate = Number($('Monitor Configuration').first().json.warnAtPercent);
const warnAtPercent = Number.isFinite(thresholdCandidate)
  ? Math.min(100, Math.max(1, thresholdCandidate))
  : 80;

const healthRow = bySource.health ?? {};
const healthBody = healthRow.body && typeof healthRow.body === 'object' ? healthRow.body : {};
const healthOk = healthRow.statusCode >= 200 && healthRow.statusCode < 300 && healthBody.status === 'ok';

const usageRow = bySource.usage ?? {};
const usageBody = usageRow.body && typeof usageRow.body === 'object' ? usageRow.body : {};
const limits = Array.isArray(usageBody.limits) ? usageBody.limits : [];
const finiteLimits = limits
  .filter((limit) => limit && typeof limit === 'object' && Number.isFinite(limit.used) && Number.isFinite(limit.max) && limit.max > 0)
  .map((limit) => ({
    key: typeof limit.key === 'string' ? limit.key : 'unnamed',
    used: limit.used,
    max: limit.max,
    period: typeof limit.period === 'string' ? limit.period : 'unknown',
    percent: Math.round((limit.used / limit.max) * 1000) / 10,
  }))
  .sort((left, right) => right.percent - left.percent);
const highest = finiteLimits[0] ?? null;
const usageWarning = highest ? highest.percent >= warnAtPercent : false;
const usageReachable = usageRow.statusCode >= 200 && usageRow.statusCode < 300;

const reportsRow = bySource.reports ?? {};
const reportsBody = reportsRow.body && typeof reportsRow.body === 'object' ? reportsRow.body : {};
const reportMeta = reportsBody.meta && typeof reportsBody.meta === 'object' ? reportsBody.meta : {};
const reportsReachable = reportsRow.statusCode >= 200 && reportsRow.statusCode < 300;

let severity = 'info';
if (!healthOk || !usageReachable || !reportsReachable) severity = 'critical';
else if (usageWarning) severity = 'warning';

const message = [
  `PipSync read-only monitor: ${severity.toUpperCase()}`,
  `Health: ${healthOk ? 'ok' : 'check required'}`,
  highest
    ? `Highest usage: ${highest.key} ${highest.used}/${highest.max} (${highest.percent}%, threshold ${warnAtPercent}%)`
    : 'Highest usage: no finite limit returned',
  `Reports: ${Number.isInteger(reportMeta.available) ? reportMeta.available : 'n/a'} available, ${Number.isInteger(reportMeta.planned) ? reportMeta.planned : 'n/a'} planned`,
  'No write request or trade execution was performed.',
].join('\n');

return [{
  json: {
    schema: 'pipsync.read-only-monitor.v1',
    severity,
    checkedAt: new Date().toISOString(),
    health: { ok: healthOk, httpStatus: Number.isFinite(healthRow.statusCode) ? healthRow.statusCode : null },
    usage: { reachable: usageReachable, thresholdPercent: warnAtPercent, highest },
    reports: {
      reachable: reportsReachable,
      available: Number.isInteger(reportMeta.available) ? reportMeta.available : null,
      planned: Number.isInteger(reportMeta.planned) ? reportMeta.planned : null,
    },
    redaction: { responseHeaders: 'omitted', errorBodies: 'omitted', credentials: 'not present' },
    notification: { previewOnly: true, message },
  },
}];
